    CONSTRAINT knowledge_documents_status_check CHECK (((status)::text = ANY ((ARRAY['DRAFT'::character varying, 'PUBLISHED'::character varying, 'ARCHIVED'::character varying])::text[])))
);


ALTER TABLE naherb.knowledge_documents OWNER TO postgres;

