    payment_method character varying(255) NOT NULL,
    payment_status character varying(255) DEFAULT 'UNPAID'::naherb.payment_status NOT NULL,
    subtotal_amount numeric(12,2) DEFAULT 0 NOT NULL,
    shipping_fee numeric(38,2) DEFAULT 0 NOT NULL,
    discount_amount numeric(38,2) DEFAULT 0 NOT NULL,
    total_amount numeric(38,2) NOT NULL,
    receiver_name character varying(255) NOT NULL,
    receiver_phone character varying(30) NOT NULL,
    receiver_email character varying(254),
    shipping_province_code character varying(30),
