    shipping_ward_code character varying(30),
    shipping_ward_name character varying(255) NOT NULL,
    shipping_address_line text NOT NULL,
    customer_note text,
    admin_note text,
    cancelled_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    final_amount numeric(38,2) NOT NULL,
    shipping_address text NOT NULL,
    receiver_address_detail text,
    receiver_address_note text,
    receiver_province_city character varying(255),
    receiver_ward_commune character varying(255),
    order_status character varying(255) NOT NULL,
    CONSTRAINT orders_amount_chk CHECK (((subtotal_amount >= (0)::numeric) AND (shipping_fee >= (0)::numeric) AND (discount_amount >= (0)::numeric) AND (total_amount >= (0)::numeric))),
    CONSTRAINT orders_order_status_check CHECK (((order_status)::text = ANY ((ARRAY['PENDING_CONFIRMATION'::character varying, 'CONFIRMED'::character varying, 'PACKING'::character varying, 'SHIPPING'::character varying, 'COMPLETED'::character varying, 'CANCELLED'::character varying])::text[])))
);


